import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"函数与预处理指令","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Function_and_Preprocessor.md","filePath":"translation/Function_and_Preprocessor.md"}`),a={name:`translation/Function_and_Preprocessor.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="函数与预处理指令" tabindex="-1">函数与预处理指令 <a class="header-anchor" href="#函数与预处理指令" aria-label="Permalink to “函数与预处理指令”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/exfunc" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/exfunc</a></p></blockquote><h2 id="函数" tabindex="-1">函数 <a class="header-anchor" href="#函数" aria-label="Permalink to “函数”">​</a></h2><h3 id="eventload" tabindex="-1">@EVENTLOAD <a class="header-anchor" href="#eventload" aria-label="Permalink to “@EVENTLOAD”">​</a></h3><p>在数据加载完成后立即调用。</p><p>由于它是事件函数，因此可以定义多个。</p><p>如果没有定义 <code>@EVENTLOAD</code>，则会转移到 <code>@SHOW_SHOP</code>（与 Eramaker 的行为相同）。</p><h3 id="title-loadgame" tabindex="-1">@TITLE_LOADGAME <a class="header-anchor" href="#title-loadgame" aria-label="Permalink to “@TITLE_LOADGAME”">​</a></h3><p>在标准标题画面中选择读取时被调用。</p><p>通过定义 <code>@TITLE_LOADGAME</code>，标题画面也可以使用自定义的读取画面。</p><p>如果没有定义，则使用标准的读取画面。</p><p>在定义了 <code>@SYSTEM_TITLE</code> 的情况下，除非显式 <code>CALL</code>，否则 <code>@TITLE_LOADGAME</code> 不会被调用。</p><h3 id="system-autosave" tabindex="-1">@SYSTEM_AUTOSAVE <a class="header-anchor" href="#system-autosave" aria-label="Permalink to “@SYSTEM_AUTOSAVE”">​</a></h3><p>在将要进行自动保存的时机被调用。</p><p>可以自行决定自动保存的内容。</p><p>如果没有定义，则使用标准的保存功能。</p><h3 id="system-title" tabindex="-1">@SYSTEM_TITLE <a class="header-anchor" href="#system-title" aria-label="Permalink to “@SYSTEM_TITLE”">​</a></h3><p>在 <code>csv</code> 加载结束时被调用。</p><p>此外，通过 <code>BEGIN TITLE</code> 也会被调用。</p><p>通过定义 <code>@SYSTEM_TITLE</code>，可以使用自定义的标题画面。</p><p>如果没有定义，则使用标准的标题画面。</p><h3 id="calltrainend" tabindex="-1">@CALLTRAINEND <a class="header-anchor" href="#calltrainend" aria-label="Permalink to “@CALLTRAINEND”">​</a></h3><p>在 <code>CALLTRAIN</code> 的自动执行结束后，由系统内部自动调用的函数。</p><p>请注意，它不是事件函数，不能多重定义。</p><h3 id="自制函数中的参数指定" tabindex="-1">自制函数中的参数指定 <a class="header-anchor" href="#自制函数中的参数指定" aria-label="Permalink to “自制函数中的参数指定”">​</a></h3><blockquote><p>※1.54u 之前与 1.60 之后的规格不同！※</p></blockquote><h4 id="格式" tabindex="-1">格式 <a class="header-anchor" href="#格式" aria-label="Permalink to “格式”">​</a></h4><p>函数侧：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>@(函数名),(参数1),{(参数2)....}</span></span>
<span class="line"><span>参数若为数值则用 ARG(:0,1,2...)，若为字符串则用 ARGS(:0,1,2...)</span></span>
<span class="line"><span>函数中用 #DIM、#DIMS 定义的私有变量也可以指定为参数</span></span></code></pre></div><p>调用侧：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>CALL (函数名),(参数1),{(参数2)....}</span></span></code></pre></div><p>参数可以使用数值表达式或字符串表达式。</p><p>把字符串字面量（常量）作为参数时，请用 <code>&quot;&quot;</code> 括起来。</p><p>把带格式的字符串字面量作为参数时，请写成 <code>@&quot;～～&quot;</code>。</p><p>除了 <code>CALL</code> 之外，<code>JUMP</code>、<code>CALLFORM</code>、<code>TRYCALL</code> 等也可以使用相同的格式。</p><p>函数侧可以指定任意数量的参数。</p><p>截至 ver1.808，如果函数侧与调用侧的型不同，无论是数值到字符串还是字符串到数值，都不会进行转换，而是直接出错。</p><p>如果想像 ver1.807 及更早版本那样，用数值调用字符串型参数，请修改<a href="./Config.html">配置设置</a>改用自动补充 <code>TOSTR</code>，或使用 <code>TOSTR</code> 函数。</p><p>参数可以省略。省略时，若没有设置初始值，数值型参数会被赋值为 0，字符串型参数会被赋值为空字符串。</p><p>在被调用的函数侧，可以通过 <code>ARG</code> 和 <code>ARGS</code> 引用传入的值。</p><p>请注意，这基本上是值传递，因此即使改变 <code>ARG</code> 的内容，也不会改变传入方原本的变量等的值。</p><p>也可以把 <code>ARG</code>、<code>ARGS</code>，或者函数中用 <code>#DIM</code>、<code>#DIMS</code> 定义的私有变量以外的变量（如 <code>A</code>、<code>STR</code>）作为参数，但有一些限制。</p><p>截至 ver1.808，使用这些变量时不能设置初始值，也不能省略参数。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;定义</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARGS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#9CDCFE;">  ～～</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">HOGEHOGE</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span></span>
<span class="line"><span style="color:#9CDCFE;">  ～～</span></span>
<span class="line"><span style="color:#6A9955;">;调用</span></span>
<span class="line"><span style="color:#6A9955;">;用变量指定</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">X</span><span style="color:#E6E6E6;"> , </span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#6A9955;">;用常量指定</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">123</span><span style="color:#E6E6E6;"> , </span><span style="color:#CE9178;">&quot;あいう&quot;</span></span>
<span class="line"><span style="color:#6A9955;">;用带格式的字符串指定</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">123</span><span style="color:#E6E6E6;"> , </span><span style="color:#CE9178;">@&quot;[</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">COUNT</span><span style="color:#569CD6;">}</span><span style="color:#CE9178;">] あいう&quot;</span></span>
<span class="line"><span style="color:#6A9955;">;用表达式指定</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">X</span><span style="color:#D4D4D4;"> +</span><span style="color:#B5CEA8;"> 10</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;あいう&quot;</span><span style="color:#D4D4D4;"> *</span><span style="color:#B5CEA8;"> 10</span></span>
<span class="line"><span style="color:#6A9955;">;参数省略——全部</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span></span>
<span class="line"><span style="color:#6A9955;">;参数省略——第 1 个参数</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, , </span><span style="color:#CE9178;">&quot;あいう&quot;</span></span>
<span class="line"><span style="color:#6A9955;">;参数省略——第 2 个参数</span></span>
<span class="line"><span style="color:#C586C0;">CALL</span><span style="color:#DCDCAA;"> FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">123</span></span></code></pre></div><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;会出错的例子&gt;</span></span>
<span class="line"><span>;错误（参数过多）</span></span>
<span class="line"><span>CALL FOOBAR, X , STR:0, Y</span></span>
<span class="line"><span>;错误（参数型不符——试图把字符串赋给数值型的第 1 个参数）</span></span>
<span class="line"><span>CALL FOOBAR, &quot;あいう&quot;, &quot;かきく&quot;</span></span>
<span class="line"><span>;错误（参数型不符——试图把数值赋给字符串型的第 2 个参数）</span></span>
<span class="line"><span>CALL FOOBAR, 123 , 456</span></span>
<span class="line"><span>&lt;能运行但不推荐的做法&gt;</span></span>
<span class="line"><span>;赋值目标可以不是 ARG、ARGS，但通常推荐使用 ARG</span></span>
<span class="line"><span>@FOOBAR, X, Y</span></span>
<span class="line"><span>;赋值目标也可以是可变的，但会降低可读性</span></span>
<span class="line"><span>@FOOBAR, ARG:X, ARG:Y</span></span>
<span class="line"><span>;可读性会降低</span></span>
<span class="line"><span>@FOOBAR, ARG:0, ARG:(ARG:0)</span></span></code></pre></div><h4 id="参数的初始值" tabindex="-1">参数的初始值 <a class="header-anchor" href="#参数的初始值" aria-label="Permalink to “参数的初始值”">​</a></h4><p>可以为函数参数设置初始值。</p><p>设置初始值时，函数侧如下所示：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>@(函数名),(参数1 = 初始值1),{(参数2 = 初始值2)....}</span></span>
<span class="line"><span>参数若为数值则用 ARG(:0,1,2...)，若为字符串则用 ARGS(:0,1,2...)，</span></span>
<span class="line"><span>或者使用函数中用 #DIM、#DIMS 定义的私有变量</span></span>
<span class="line"><span>指定除此之外的内容时，不能设置初始值。</span></span></code></pre></div><p>可指定的初始值只能是常量和常数字符串，不能指定变量。</p><p>字符串的初始值请用 <code>&quot;&quot;</code> 括起来。</p><p>设置了初始值后，如果调用侧省略了参数，就会把初始值赋给该参数。</p><p>如果没有省略而正常调用函数，则会照常把传入的值赋给 <code>ARG</code> 和 <code>ARGS</code>。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;设置初始值（也可以只省略一部分）</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FUNCTION</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARGS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#CE9178;"> &quot;かきく&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 111</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 200</span></span>
<span class="line"><span style="color:#9CDCFE;">  ～～</span></span>
<span class="line"><span style="color:#6A9955;">;错误（初始值只能是常量和常数字符串）</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> MASTER</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">ARG</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">1</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> TARGET</span></span>
<span class="line"><span style="color:#6A9955;">;给 ARG、ARGS 以及函数中用 #DIM、#DIMS 定义的私有变量以外的参数设置初始值会被忽略</span></span>
<span class="line"><span style="color:#6A9955;">;因此无法按预期工作</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">FOOBAR</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">X</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 5</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">Y</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 4</span></span></code></pre></div><h4 id="参数的引用传递" tabindex="-1">参数的引用传递 <a class="header-anchor" href="#参数的引用传递" aria-label="Permalink to “参数的引用传递”">​</a></h4><p>从 ver1.810 开始，通过把引用型变量作为形参，就可以实现参数的引用传递。</p><p>关于引用型变量的定义方法，请参阅<a href="./Custom_Variable.html#引用型变量">引用型变量</a>一节。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;&lt;xxx.ERB&gt;</span></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">SYSTEM_TITLE</span></span>
<span class="line"><span style="color:#9CDCFE;">  A</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#C586C0;">  CALL</span><span style="color:#DCDCAA;"> TEST</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">A</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#9CDCFE;">  B</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#C586C0;">  CALL</span><span style="color:#DCDCAA;"> TEST</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">B</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTFORML</span><span style="color:#E6E6E6;"> A == </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">A</span><span style="color:#569CD6;">}</span></span>
<span class="line"><span style="color:#569CD6;">  PRINTFORML</span><span style="color:#E6E6E6;"> B == </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">B</span><span style="color:#569CD6;">}</span></span>
<span class="line"><span style="color:#569CD6;">  WAIT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">TEST</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">HOGE</span><span style="color:#E6E6E6;">)</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">DIM</span><span style="color:#569CD6;"> REF </span><span style="color:#9CDCFE;">HOGE</span></span>
<span class="line"><span style="color:#9CDCFE;">  HOGE</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 100</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span></span></code></pre></div><p>执行结果：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>A == 100</span></span>
<span class="line"><span>B == 100</span></span></code></pre></div><p>在上面的例子中，函数 <code>TEST</code> 的形参是引用型变量。</p><p>第一次调用 <code>TEST</code> 时，<code>HOGE</code> 会引用实参 <code>A</code>。</p><p>在函数 <code>TEST</code> 中执行 <code>HOGE = 100</code>，就会把 <code>100</code> 赋给引用目标变量 <code>A</code>，因此第一次 <code>PRINTFORML</code> 的结果为 100。</p><p>同样地，第二次调用 <code>TEST</code> 时会把 <code>100</code> 赋给变量 <code>B</code>，第二次 <code>PRINTFORML</code> 的结果也为 100。</p><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to “属性”">​</a></h2><p>属性是决定函数规格和行为的预处理指令。</p><p>给函数书写以 <code>#</code> 开头的预处理指令时，必须紧跟在函数声明之下。</p><h3 id="only" tabindex="-1">#ONLY <a class="header-anchor" href="#only" aria-label="Permalink to “#ONLY”">​</a></h3><p>事件函数专用的属性。</p><p>如果存在指定了 <code>#ONLY</code> 的事件函数，则只有这一个会被执行，同名的其他事件函数不会被执行。</p><p>另外，即使存在多个指定了 <code>#ONLY</code> 的同名事件函数，被执行的也只有「最初的那一个」。</p><h3 id="function" tabindex="-1">#FUNCTION <a class="header-anchor" href="#function" aria-label="Permalink to “#FUNCTION”">​</a></h3><p>数值型表达式内函数的属性。</p><p>表达式内函数不能通过通常的 <code>RETURN</code> 结束，而必须用 <code>RETURNF &lt;数值表达式&gt;</code> 结束。</p><p>详情请参阅<a href="./Custom_Expression.html">用户自定义表达式内函数</a>。</p><h3 id="functions" tabindex="-1">#FUNCTIONS <a class="header-anchor" href="#functions" aria-label="Permalink to “#FUNCTIONS”">​</a></h3><p>字符串型表达式内函数的属性。</p><p>表达式内函数不能通过通常的 <code>RETURN</code> 结束，而必须用 <code>RETURNF &lt;字符串表达式&gt;</code> 结束。</p><p>详情请参阅<a href="./Custom_Expression.html">用户自定义表达式内函数</a>。</p><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to “定义”">​</a></h2><p>定义是用于定义变量名称及其规格的预处理指令。</p><p>给函数书写以 <code>#</code> 开头的预处理指令时，必须紧跟在函数声明之下。</p><h3 id="localsize-常数表达式-与-localssize-常数表达式" tabindex="-1">#LOCALSIZE &lt;常数表达式&gt; 与 #LOCALSSIZE &lt;常数表达式&gt; <a class="header-anchor" href="#localsize-常数表达式-与-localssize-常数表达式" aria-label="Permalink to “#LOCALSIZE &lt;常数表达式&gt; 与 #LOCALSSIZE &lt;常数表达式&gt;”">​</a></h3><p>这是为每个函数分别指定 <code>LOCAL</code> 和 <code>LOCALS</code> 元素数的预处理指令。</p><p>常数表达式的计算结果必须是大于 0 的整数；否则，或表达式中包含变量，或给出了无法解释的字符串时，都会被忽略。</p><p>被忽略或未使用该预处理指令时，会照常使用 <code>VariableSize.csv</code> 中的设置值。</p><p>如果对事件函数使用这个预处理指令，则会采用最先被执行的那个函数的设置（截至 ver1800）。</p><h3 id="dim" tabindex="-1">#DIM <a class="header-anchor" href="#dim" aria-label="Permalink to “#DIM”">​</a></h3><p>用户自定义变量的声明。</p><p>在 <code>ERB</code> 的特定函数内使用时，可以定义只能在该函数内使用的数值型变量。详情请参阅<a href="./Custom_Variable.html">用户自定义变量</a>。</p><p>另外，在 <code>ERH</code> 中使用时，可以定义在所有函数间共享值的数值型变量。详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h3 id="dims" tabindex="-1">#DIMS <a class="header-anchor" href="#dims" aria-label="Permalink to “#DIMS”">​</a></h3><p>用户自定义变量的声明。</p><p>在 <code>ERB</code> 的特定函数内使用时，可以定义只能在该函数内使用的字符串型变量。详情请参阅<a href="./Custom_Variable.html">用户自定义变量</a>。</p><p>另外，在 <code>ERH</code> 中使用时，可以定义在所有函数间共享值的字符串型变量。详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h3 id="define" tabindex="-1">#DEFINE <a class="header-anchor" href="#define" aria-label="Permalink to “#DEFINE”">​</a></h3><p><code>DEFINE</code> 宏的声明。</p><p>在 <code>ERH</code> 中使用时，可以把所有 <code>ERB</code> 代码中的某个字符串替换为预先定义好的另一个字符串。详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h2 id="代表特殊区块的行" tabindex="-1">代表特殊区块的行 <a class="header-anchor" href="#代表特殊区块的行" aria-label="Permalink to “代表特殊区块的行”">​</a></h2><p>这些是预处理指令行。</p><p>在书写它们的同一行中，不能紧跟着再书写指令、函数或注释等内容。</p><p>Eramaker 无法解释这些内容，因此根据情况编写代码时可能需要使用 <code>;!;</code>。</p><h3 id="skipstart-与-skipend" tabindex="-1">[SKIPSTART] 与 [SKIPEND] <a class="header-anchor" href="#skipstart-与-skipend" aria-label="Permalink to “[SKIPSTART] 与 [SKIPEND]”">​</a></h3><p>写在 <code>[SKIPSTART]</code> 到 <code>[SKIPEND]</code> 之间的行，Emuera 不会读取和执行。</p><p>当想要故意改变 Emuera 和 Eramaker 之间的行为时会用到它。</p><p>请用它来书写不希望 Emuera 执行的语句。</p><p>另外，与 <code>;!;</code> 一起使用时，还可以书写不希望 Emuera 以外执行的语句。</p><p>详情请参阅<a href="./General.html">常规</a>一节。</p><h3 id="if-xxx-与-elseif-xxx-与-else-与-endif" tabindex="-1">[IF XXX] 与 [ELSEIF XXX] 与 [ELSE] 与 [ENDIF] <a class="header-anchor" href="#if-xxx-与-elseif-xxx-与-else-与-endif" aria-label="Permalink to “[IF XXX] 与 [ELSEIF XXX] 与 [ELSE] 与 [ENDIF]”">​</a></h3><p>根据名为 <code>XXX</code> 的宏是否已定义，可以分支决定是否执行多行内容。</p><p>详情请参阅<a href="./Header_File.html">头文件（ERH）</a>。</p><h3 id="if-debug-与-endif" tabindex="-1">[IF_DEBUG] 与 [ENDIF] <a class="header-anchor" href="#if-debug-与-endif" aria-label="Permalink to “[IF_DEBUG] 与 [ENDIF]”">​</a></h3><p>写在 <code>[IF_DEBUG]</code> 到 <code>[ENDIF]</code> 之间的行，只在调试模式下执行。</p><p>非调试模式下，它会被视为注释行，不会被执行。</p><p>不过，<code>DEBUG</code> 系指令在非调试模式下原本就会被忽略，所以没有必要在行首加上 <code>;#;</code>。</p><p>同样，调试变量在非调试模式下是空字符串或 0，因此不必担心出错。</p><p>关于调试模式的详情，请参阅<a href="./Debug_Mode.html">调试模式</a>。</p><h3 id="if-ndebug-与-endif" tabindex="-1">[IF_NDEBUG] 与 [ENDIF] <a class="header-anchor" href="#if-ndebug-与-endif" aria-label="Permalink to “[IF_NDEBUG] 与 [ENDIF]”">​</a></h3><p>写在 <code>[IF_NDEBUG]</code> 到 <code>[ENDIF]</code> 之间的行，只在非调试模式下执行。</p><p>调试模式下，它会被视为注释行，不会被执行。</p><p>判断与 <code>[IF_DEBUG]</code> 正好相反。</p><p>关于调试模式的详情，请参阅<a href="./Debug_Mode.html">调试模式</a>。</p>`,122)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};